active_directory.template:
# Bulk Create AD Users from CSV
#Requires -Modules ActiveDirectory
$csv = Import-Csv '{{csv_path}}'
$securePass = ConvertTo-SecureString '{{initial_password}}' -AsPlainText -Force
foreach ($row in $csv) {
    $DisplayName = if ([string]::IsNullOrWhiteSpace($row.Surname)) { $row.GivenName } else { "$($row.GivenName) $($row.Surname)" }
    $params = @{
        Name = $DisplayName
        SamAccountName = $row.SamAccountName
        UserPrincipalName = $row.UserPrincipalName
        GivenName = $row.GivenName
        Surname = $row.Surname
        AccountPassword = $securePass
        Enabled = $true
    }
    if ($row.OU) { $params['Path'] = $row.OU }
    elseif ('{{ou_path}}') { $params['Path'] = '{{ou_path}}' }
    if ($row.Description) { $params['Description'] = $row.Description }
    New-ADUser @params
}

network_tools.template:
# Port Scan (common ports)
$ports = '{{port}}'
foreach ($p in $ports) {
    $result = Test-NetConnection -ComputerName '{{hostname}}' -Port $p -WarningAction SilentlyContinue -ErrorAction SilentlyContinue
    if ($result.TcpTestSucceeded) { Write-Host "Port $p - OPEN" -ForegroundColor Green } else { Write-Host "Port $p - Closed" -ForegroundColor Gray }
}

security.template:
# Last Logon Report
#Requires -Modules ActiveDirectory
$ou = '{{search_base}}'
if ($ou) { Get-ADUser -Filter * -SearchBase $ou -Properties LastLogonDate | Select-Object Name, SamAccountName, LastLogonDate | Sort-Object LastLogonDate -Descending | Format-Table -AutoSize }
else { Get-ADUser -Filter * -Properties LastLogonDate | Select-Object Name, SamAccountName, LastLogonDate | Sort-Object LastLogonDate -Descending | Format-Table -AutoSize }

system_maintenance.template:
# Check Critical Services
$svcs = '{{services}}' -split ',' | ForEach-Object { $_.Trim() }
foreach ($s in $svcs) {
    try {
        $svc = Get-Service -Name $s -ErrorAction Stop
        $status = if ($svc.Status -eq 'Running') { 'Running' } else { 'Stopped' }
        Write-Host "$s : $status"
    } catch { Write-Host "$s : Not Found" -ForegroundColor Yellow }
}

domain_migration.template:
# ==========================================================
# DOMAIN MIGRATION – SMART BACKUP + ONEDRIVE VALIDATION + BREAKGLASS
# ==========================================================

param(
    [string]$Destination = "{{Destination}}",
    [string]$BackupDesktop = "{{BackupDesktop}}",
    [string]$BackupDocuments = "{{BackupDocuments}}",
    [string]$BackupPictures = "{{BackupPictures}}",
    [string]$BackupDownloads = "{{BackupDownloads}}",
    [string]$BackupFavorites = "{{BackupFavorites}}",
    [string]$BackupMusic = "{{BackupMusic}}",
    [string]$BackupVideos = "{{BackupVideos}}",
    [string]$BackupLinks = "{{BackupLinks}}",
    [string]$BackupSavedGames = "{{BackupSavedGames}}",
    [string]$BackupContacts = "{{BackupContacts}}",
    [string]$BackupSearches = "{{BackupSearches}}",
    [string]$Backup3DObjects = "{{Backup3DObjects}}",
    [string]$BackupOneDrive = "{{BackupOneDrive}}",
    [string]$BackupOutlook = "{{BackupOutlook}}",
    [string]$BackupChrome = "{{BackupChrome}}",
    [string]$BackupEdge = "{{BackupEdge}}",
    [string]$BackupFirefox = "{{BackupFirefox}}",
    [string]$BackupPrinters = "{{BackupPrinters}}"
)

Write-Host "=== DOMAIN MIGRATION SMART BACKUP STARTED ==="

if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]"Administrator")) {
    Write-Error "Run this script as Administrator."
    exit 1
}

# CREATE / VERIFY BREAKGLASS
$BreakGlassUserName   = "IT-BreakGlass"
$BreakGlassPlainPass  = "S0mething!VeryStr0ng#2026"
$BreakGlassSecurePass = ConvertTo-SecureString $BreakGlassPlainPass -AsPlainText -Force

try {
    $ExistingLocalUser = Get-LocalUser -Name $BreakGlassUserName -ErrorAction SilentlyContinue
    if (-not $ExistingLocalUser) {
        New-LocalUser -Name $BreakGlassUserName -Password $BreakGlassSecurePass -FullName "IT Emergency Admin" -Description "Local emergency admin" -PasswordNeverExpires:$true -UserMayNotChangePassword:$true -AccountNeverExpires:$true | Out-Null
    }
    elseif ($ExistingLocalUser.Enabled -eq $false) { Enable-LocalUser -Name $BreakGlassUserName }
    $IsBreakGlassAdmin = Get-LocalGroupMember -Group "Administrators" -ErrorAction SilentlyContinue | Where-Object { $_.Name -like "*\$BreakGlassUserName" -or $_.Name -eq $BreakGlassUserName }
    if (-not $IsBreakGlassAdmin) { Add-LocalGroupMember -Group "Administrators" -Member $BreakGlassUserName }
} catch { Write-Error "Failed BreakGlass: $($_.Exception.Message)"; exit 1 }

# FUNCTIONS
function Test-ValidUserProfile { param([string]$Path)
    if (-not (Test-Path $Path)) { return $false }
    $Leaf = Split-Path $Path -Leaf
    $Excluded = @('Public','Default','Default User','All Users','Administrator','WDAGUtilityAccount')
    if ($Leaf -in $Excluded -or $Leaf -match '^TEMP\.') { return $false }
    return (Test-Path (Join-Path $Path 'NTUSER.DAT'))
}

function Get-TargetUserProfile {
    $CandidatePaths = [System.Collections.Generic.List[string]]::new()
    try { $LastUser = (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI" -ErrorAction Stop).LastLoggedOnUser } catch { $LastUser = $null }
    if ($LastUser) {
        $UserPart = ($LastUser -split "\\")[-1]; if ($UserPart.StartsWith(".\")) { $UserPart = $UserPart.Substring(2) }
        if ($UserPart) { $CandidatePaths.Add("C:\Users\$UserPart") }
    }
    try {
        foreach ($p in Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList' -ErrorAction SilentlyContinue) {
            $pi = Get-ItemProperty $p.PSPath -ErrorAction SilentlyContinue
            if ($pi.ProfileImagePath -like 'C:\Users\*') {
                $exp = [Environment]::ExpandEnvironmentVariables($pi.ProfileImagePath)
                $CandidatePaths.Add($exp)
            }
        }
    } catch {}
    $Seen = @{}
    foreach ($Path in $CandidatePaths) {
        if ([string]::IsNullOrWhiteSpace($Path) -or $Seen[$Path.ToLower()]) { continue }
        $Seen[$Path.ToLower()] = $true
        if (Test-ValidUserProfile -Path $Path) {
            return [pscustomobject]@{ UserName = (Split-Path $Path -Leaf); ProfileDir = $Path }
        }
    }
    return $null
}

function Expand-UserPath { param([string]$PathValue, [string]$UserProfileDir = $null)
    if ([string]::IsNullOrWhiteSpace($PathValue)) { return $null }
    if ($UserProfileDir) { $PathValue = $PathValue -replace '%USERPROFILE%',$UserProfileDir -replace '\$env:USERPROFILE',$UserProfileDir }
    return [Environment]::ExpandEnvironmentVariables($PathValue)
}

function Invoke-RoboBackup { param([string]$Source, [string]$Destination)
    if (-not (Test-Path $Source)) { return }
    New-Item -ItemType Directory -Path $Destination -Force | Out-Null
    & robocopy $Source $Destination /E /COPY:DAT /R:1 /W:1 /NFL /NDL /NP /XJ | Out-Null
    if ($LASTEXITCODE -ge 8) { throw "Robocopy failed: $Source -> $Destination" }
}

# DETECT PROFILE
$ProfileInfo = Get-TargetUserProfile
if (-not $ProfileInfo) { Write-Error "No valid user profile found."; exit 1 }
$User = $ProfileInfo.UserName
$ProfileDir = $ProfileInfo.ProfileDir
$BackupRoot = if ($Destination) { Join-Path $Destination.TrimEnd('\') $User } else { "C:\DomainMigration\$User" }
New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null

# RESOLVE SID
try { $Sid = (New-Object System.Security.Principal.NTAccount($User)).Translate([System.Security.Principal.SecurityIdentifier]).Value }
catch { Write-Error "Could not resolve SID for $User"; exit 1 }

$CurrentSid = ([Security.Principal.WindowsIdentity]::GetCurrent().User).Value
$RunningAsSystem = ($CurrentSid -eq 'S-1-5-18')
$UserShellKey = "Registry::HKEY_USERS\$Sid\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders"

if ($RunningAsSystem -or -not (Test-Path $UserShellKey)) {
    $DesktopPath = Join-Path $ProfileDir 'Desktop'
    $DocsPath = Join-Path $ProfileDir 'Documents'
    $PicturesPath = Join-Path $ProfileDir 'Pictures'
} else {
    try {
        $UShell = Get-ItemProperty $UserShellKey -ErrorAction Stop
        $DesktopPath = Expand-UserPath $UShell.Desktop -UserProfileDir $ProfileDir
        $DocsPath = Expand-UserPath $UShell.Personal -UserProfileDir $ProfileDir
        $PicturesPath = Expand-UserPath $UShell.'My Pictures' -UserProfileDir $ProfileDir
        if (-not $DesktopPath) { $DesktopPath = Join-Path $ProfileDir 'Desktop' }
        if (-not $DocsPath) { $DocsPath = Join-Path $ProfileDir 'Documents' }
        if (-not $PicturesPath) { $PicturesPath = Join-Path $ProfileDir 'Pictures' }
    } catch {
        $DesktopPath = Join-Path $ProfileDir 'Desktop'
        $DocsPath = Join-Path $ProfileDir 'Documents'
        $PicturesPath = Join-Path $ProfileDir 'Pictures'
    }
}

$DesktopInOD = $DesktopPath -like '*OneDrive*'
$DocsInOD = $DocsPath -like '*OneDrive*'
$PicturesInOD = $PicturesPath -like '*OneDrive*'

# CORE FOLDERS (Desktop, Documents, Pictures)
if ($BackupDesktop -eq 'true' -and (Test-Path $DesktopPath)) { Write-Host "Backing up Desktop..."; try { Invoke-RoboBackup -Source $DesktopPath -Destination (Join-Path $BackupRoot "Desktop") } catch { Write-Warning $_.Exception.Message } }
if ($BackupDocuments -eq 'true' -and (Test-Path $DocsPath)) { Write-Host "Backing up Documents..."; try { Invoke-RoboBackup -Source $DocsPath -Destination (Join-Path $BackupRoot "Documents") } catch { Write-Warning $_.Exception.Message } }
if ($BackupPictures -eq 'true' -and (Test-Path $PicturesPath)) { Write-Host "Backing up Pictures..."; try { Invoke-RoboBackup -Source $PicturesPath -Destination (Join-Path $BackupRoot "Pictures") } catch { Write-Warning $_.Exception.Message } }

# EXTRA FOLDERS
$ExtraMap = @{
    Downloads = $BackupDownloads
    Favorites = $BackupFavorites
    Music = $BackupMusic
    Videos = $BackupVideos
    Links = $BackupLinks
    "Saved Games" = $BackupSavedGames
    Contacts = $BackupContacts
    Searches = $BackupSearches
    "3D Objects" = $Backup3DObjects
    OneDrive = $BackupOneDrive
}
foreach ($Folder in $ExtraMap.Keys) {
    if (($ExtraMap[$Folder]) -eq 'true') {
        $Src = Join-Path $ProfileDir $Folder
        if (Test-Path $Src) {
            Write-Host "Backing up $Folder..."
            try { Invoke-RoboBackup -Source $Src -Destination (Join-Path $BackupRoot $Folder) } catch { Write-Warning $_.Exception.Message }
        }
    }
}

# OUTLOOK
if ($BackupOutlook -eq 'true') {
    $Outlook = Join-Path $ProfileDir "AppData\Roaming\Microsoft\Outlook"
    if (Test-Path $Outlook) { Write-Host "Backing up Outlook..."; try { Invoke-RoboBackup -Source $Outlook -Destination (Join-Path $BackupRoot "Outlook") } catch { Write-Warning $_.Exception.Message } }
}

# BROWSERS
if ($BackupChrome -eq 'true') {
    $Chrome = Join-Path $ProfileDir "AppData\Local\Google\Chrome\User Data"
    if (Test-Path $Chrome) { Write-Host "Backing up Chrome..."; try { Invoke-RoboBackup -Source $Chrome -Destination (Join-Path $BackupRoot "Chrome") } catch { Write-Warning $_.Exception.Message } }
}
if ($BackupEdge -eq 'true') {
    $Edge = Join-Path $ProfileDir "AppData\Local\Microsoft\Edge\User Data"
    if (Test-Path $Edge) { Write-Host "Backing up Edge..."; try { Invoke-RoboBackup -Source $Edge -Destination (Join-Path $BackupRoot "Edge") } catch { Write-Warning $_.Exception.Message } }
}
if ($BackupFirefox -eq 'true') {
    $Firefox = Join-Path $ProfileDir "AppData\Roaming\Mozilla"
    if (Test-Path $Firefox) { Write-Host "Backing up Firefox..."; try { Invoke-RoboBackup -Source $Firefox -Destination (Join-Path $BackupRoot "Firefox") } catch { Write-Warning $_.Exception.Message } }
}

# PRINTERS
if ($BackupPrinters -eq 'true') {
    $PrinterDir = Join-Path $BackupRoot "Printers"
    New-Item -ItemType Directory -Path $PrinterDir -Force | Out-Null
    try {
        Import-Module PrintManagement -ErrorAction Stop
        $Printers = Get-Printer -ErrorAction SilentlyContinue | Sort-Object Name
        $Ports = Get-PrinterPort -ErrorAction SilentlyContinue
        $Drivers = Get-PrinterDriver -ErrorAction SilentlyContinue
        $Default = ($Printers | Where-Object Default | Select-Object -First 1).Name
        $PrinterObjects = foreach ($p in $Printers) { [pscustomobject]@{ Name=$p.Name; DriverName=$p.DriverName; PortName=$p.PortName; IsDefault=($p.Name -eq $Default) } }
        @{ ComputerName=$env:COMPUTERNAME; CollectedAt=(Get-Date).ToString("s"); Printers=$PrinterObjects; Ports=$Ports; Drivers=$Drivers } | ConvertTo-Json -Depth 6 | Out-File (Join-Path $PrinterDir "Printers.json") -Encoding UTF8
        pnputil.exe /export-driver * (Join-Path $PrinterDir "Drivers") 2>$null
    } catch { Write-Warning "Printer backup failed: $($_.Exception.Message)" }
}

# SUMMARY
$TotalItems = (Get-ChildItem $BackupRoot -Recurse -Force -ErrorAction SilentlyContinue | Measure-Object).Count
$Summary = "User: $User`nProfileDir: $ProfileDir`nSID: $Sid`nBackupRoot: $BackupRoot`nTotalItems: $TotalItems`nComputerName: $env:COMPUTERNAME`nExecutedAs: $([System.Security.Principal.WindowsIdentity]::GetCurrent().Name)`nCompleted: $(Get-Date)"
$Summary | Out-File (Join-Path $BackupRoot "BackupSummary.txt") -Encoding UTF8
New-Item (Join-Path $BackupRoot "BACKUP_COMPLETED.txt") -ItemType File -Force | Out-Null
Write-Host "=== DOMAIN MIGRATION BACKUP COMPLETED ==="

# ==========================================================
# DOMAIN MIGRATION – FULL RESTORE
# - Runs after join to new domain
# - Detects current target user profile safely
# - Restores user data from C:\DomainMigration\<User>
# - Restores Outlook / Browsers
# - Restores printers from snapshot
# - Optionally sets default printer
# ==========================================================

Write-Host "=== DOMAIN MIGRATION RESTORE STARTED ==="

# ----------------------------------------------------------
# GUARDRAILS – MUST RUN AS ADMIN
# ----------------------------------------------------------
if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
    [Security.Principal.WindowsBuiltInRole]"Administrator")) {
    Write-Error "Run this script as Administrator."
    exit 1
}

# ----------------------------------------------------------
# CONFIG
# ----------------------------------------------------------
$MigrationRoot = "C:\DomainMigration"
$SetDefaultPrinter = $true
$RestoreBrowsers = $true
$RestoreOutlook = $true
$RestorePrinters = $true

# Optional:
# If you want to force a specific backup user folder name, set it here.
# Example: $BackupUserOverride = "igal"
$BackupUserOverride = $null

# ----------------------------------------------------------
# FUNCTIONS
# ----------------------------------------------------------
function Test-ValidUserProfile {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    if (-not (Test-Path $Path)) { return $false }

    $Leaf = Split-Path $Path -Leaf

    $Excluded = @(
        'Public',
        'Default',
        'Default User',
        'All Users',
        'Administrator',
        'WDAGUtilityAccount'
    )

    if ($Leaf -in $Excluded) { return $false }
    if ($Leaf -match '^TEMP\.') { return $false }
    if (-not (Test-Path (Join-Path $Path 'NTUSER.DAT'))) { return $false }

    return $true
}

function Get-TargetUserProfile {
    Write-Host "Detecting current target user profile..."

    $CandidatePaths = New-Object System.Collections.Generic.List[string]

    try {
        $LastUser = (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI" -ErrorAction Stop).LastLoggedOnUser
    }
    catch {
        $LastUser = $null
    }

    if ($LastUser) {
        Write-Host "LastLoggedOnUser raw value: $LastUser"

        $UserPart = $LastUser
        if ($LastUser -match "\\") {
            $UserPart = $LastUser.Split("\")[-1]
        }

        if ($UserPart.StartsWith(".\")) {
            $UserPart = $UserPart.Substring(2)
        }

        if ($UserPart) {
            $CandidatePaths.Add("C:\Users\$UserPart")
        }
    }

    try {
        $ProfileListKey = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList'
        $ProfileCandidates = foreach ($p in Get-ChildItem $ProfileListKey -ErrorAction SilentlyContinue) {
            $pi = Get-ItemProperty $p.PSPath -ErrorAction SilentlyContinue
            if ($pi.ProfileImagePath) {
                $ExpandedPath = [Environment]::ExpandEnvironmentVariables($pi.ProfileImagePath)
                if ($ExpandedPath -like 'C:\Users\*') {
                    [pscustomobject]@{
                        Path          = $ExpandedPath
                        LastWriteTime = (Get-Item $ExpandedPath -ErrorAction SilentlyContinue).LastWriteTime
                    }
                }
            }
        }

        foreach ($pc in ($ProfileCandidates | Sort-Object LastWriteTime -Descending)) {
            if ($pc.Path) {
                $CandidatePaths.Add($pc.Path)
            }
        }
    }
    catch {}

    $Seen = @{}
    foreach ($Path in $CandidatePaths) {
        if ([string]::IsNullOrWhiteSpace($Path)) { continue }

        $PathKey = $Path.ToLower()
        if ($Seen.ContainsKey($PathKey)) { continue }
        $Seen[$PathKey] = $true

        Write-Host "Testing profile candidate: $Path"

        if (Test-ValidUserProfile -Path $Path) {
            $UserName = Split-Path $Path -Leaf
            Write-Host "Selected profile: $Path"
            return [pscustomobject]@{
                UserName   = $UserName
                ProfileDir = $Path
            }
        }
    }

    return $null
}

function Invoke-RoboRestore {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Source,

        [Parameter(Mandatory = $true)]
        [string]$Destination
    )

    if (-not (Test-Path $Source)) {
        Write-Host "Restore source does not exist, skipping: $Source"
        return
    }

    New-Item -ItemType Directory -Path $Destination -Force | Out-Null

    & robocopy $Source $Destination /E /COPY:DAT /DCOPY:DAT /R:1 /W:1 /NFL /NDL /NP /XJ | Out-Null
    $RoboExit = $LASTEXITCODE

    if ($RoboExit -ge 8) {
        throw "Robocopy restore failed for '$Source' -> '$Destination' with exit code $RoboExit"
    }
}

function Find-BackupRoot {
    param(
        [string]$MigrationRoot,
        [string]$DetectedUser,
        [string]$BackupUserOverride
    )

    if ($BackupUserOverride) {
        $Forced = Join-Path $MigrationRoot $BackupUserOverride
        if (Test-Path $Forced) {
            Write-Host "Using forced backup source: $Forced"
            return $Forced
        }
        else {
            throw "Forced backup folder not found: $Forced"
        }
    }

    $Candidate1 = Join-Path $MigrationRoot $DetectedUser
    if (Test-Path $Candidate1) {
        Write-Host "Using matching backup source: $Candidate1"
        return $Candidate1
    }

    $Candidates = Get-ChildItem $MigrationRoot -Directory -ErrorAction SilentlyContinue |
        Where-Object {
            Test-Path (Join-Path $_.FullName 'BACKUP_COMPLETED.txt')
        } |
        Sort-Object LastWriteTime -Descending

    if ($Candidates.Count -eq 1) {
        Write-Host "Only one backup source found, using: $($Candidates[0].FullName)"
        return $Candidates[0].FullName
    }

    if ($Candidates.Count -gt 1) {
        Write-Warning "Multiple backup folders found. Using most recent: $($Candidates[0].FullName)"
        return $Candidates[0].FullName
    }

    throw "No valid backup source found under $MigrationRoot"
}

function Stop-UserApps {
    Write-Host "Stopping user apps before restore..."

    $Processes = @(
        "OUTLOOK",
        "ONEDRIVE",
        "chrome",
        "msedge",
        "firefox"
    )

    foreach ($p in $Processes) {
        try {
            Get-Process -Name $p -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        }
        catch {}
    }

    Start-Sleep -Seconds 2
}

function Restore-PrinterDrivers {
    param(
        [string]$DriverExportPath
    )

    if (-not (Test-Path $DriverExportPath)) {
        Write-Host "Printer driver export path not found, skipping driver import."
        return
    }

    $InfFiles = Get-ChildItem -Path $DriverExportPath -Recurse -Filter *.inf -ErrorAction SilentlyContinue
    foreach ($inf in $InfFiles) {
        try {
            Write-Host "Importing printer driver package: $($inf.FullName)"
            pnputil.exe /add-driver "`"$($inf.FullName)`"" /install | Out-Null
        }
        catch {
            Write-Warning "Failed importing driver package: $($inf.FullName)"
        }
    }
}

function Restore-PrintersFromJson {
    param(
        [string]$JsonPath,
        [bool]$SetDefaultPrinter = $true
    )

    if (-not (Test-Path $JsonPath)) {
        Write-Host "Printer JSON not found, skipping printer restore."
        return
    }

    try {
        Import-Module PrintManagement -ErrorAction Stop
    }
    catch {
        Write-Warning "PrintManagement module unavailable. Skipping printer restore."
        return
    }

    try {
        $Snapshot = Get-Content $JsonPath -Raw -Encoding UTF8 | ConvertFrom-Json -ErrorAction Stop
    }
    catch {
        Write-Warning "Failed parsing printer snapshot JSON: $($_.Exception.Message)"
        return
    }

    if (-not $Snapshot.Printers) {
        Write-Host "No printers found in snapshot."
        return
    }

    # Restore ports first if possible
    if ($Snapshot.Ports) {
        foreach ($Port in $Snapshot.Ports) {
            try {
                $ExistingPort = Get-PrinterPort -Name $Port.Name -ErrorAction SilentlyContinue
                if (-not $ExistingPort) {
                    # Try TCP port creation only when enough data exists
                    if ($Port.PrinterHostAddress) {
                        Write-Host "Creating printer port: $($Port.Name)"
                        Add-PrinterPort -Name $Port.Name -PrinterHostAddress $Port.PrinterHostAddress -ErrorAction Stop
                    }
                    else {
                        Write-Host "Skipping port creation for $($Port.Name) (unsupported or missing host address)"
                    }
                }
                else {
                    Write-Host "Printer port already exists: $($Port.Name)"
                }
            }
            catch {
                Write-Warning "Failed to create printer port $($Port.Name): $($_.Exception.Message)"
            }
        }
    }

    # Restore printers
    foreach ($Printer in $Snapshot.Printers) {
        try {
            $ExistingPrinter = Get-Printer -Name $Printer.Name -ErrorAction SilentlyContinue
            if ($ExistingPrinter) {
                Write-Host "Printer already exists: $($Printer.Name)"
                continue
            }

            Write-Host "Creating printer: $($Printer.Name)"
            Add-Printer -Name $Printer.Name -DriverName $Printer.DriverName -PortName $Printer.PortName -ErrorAction Stop
        }
        catch {
            Write-Warning "Failed to restore printer $($Printer.Name): $($_.Exception.Message)"
        }
    }

    if ($SetDefaultPrinter) {
        try {
            $DefaultPrinter = $Snapshot.Printers | Where-Object { $_.IsDefault -eq $true } | Select-Object -First 1
            if ($DefaultPrinter) {
                $PrinterNameEscaped = $DefaultPrinter.Name.Replace('\', '\\')
                Write-Host "Setting default printer: $($DefaultPrinter.Name)"
                $null = Start-Process -FilePath "rundll32.exe" `
                    -ArgumentList "printui.dll,PrintUIEntry /y /n `"$($DefaultPrinter.Name)`"" `
                    -Wait -PassThru -WindowStyle Hidden
            }
        }
        catch {
            Write-Warning "Failed to set default printer: $($_.Exception.Message)"
        }
    }
}

# ----------------------------------------------------------
# DETECT CURRENT TARGET PROFILE
# ----------------------------------------------------------
$ProfileInfo = Get-TargetUserProfile

if (-not $ProfileInfo) {
    Write-Error "No valid current user profile found."
    exit 1
}

$CurrentUser = $ProfileInfo.UserName
$ProfileDir  = $ProfileInfo.ProfileDir

Write-Host "Detected restore target user: $CurrentUser"
Write-Host "Detected restore target profile: $ProfileDir"

# ----------------------------------------------------------
# FIND BACKUP SOURCE
# ----------------------------------------------------------
try {
    $BackupRoot = Find-BackupRoot -MigrationRoot $MigrationRoot -DetectedUser $CurrentUser -BackupUserOverride $BackupUserOverride
}
catch {
    Write-Error $_.Exception.Message
    exit 1
}

Write-Host "Using backup source: $BackupRoot"

# ----------------------------------------------------------
# PREP
# ----------------------------------------------------------
Stop-UserApps

$RestoreLog = New-Object System.Collections.Generic.List[string]

function Add-RestoreLog {
    param([string]$Text)
    $RestoreLog.Add($Text) | Out-Null
    Write-Host $Text
}

# ----------------------------------------------------------
# RESTORE CORE FOLDERS
# ----------------------------------------------------------
$FolderMap = @(
    @{ Name = "Desktop";   Source = (Join-Path $BackupRoot "Desktop");   Destination = (Join-Path $ProfileDir "Desktop") },
    @{ Name = "Documents"; Source = (Join-Path $BackupRoot "Documents"); Destination = (Join-Path $ProfileDir "Documents") },
    @{ Name = "Pictures";  Source = (Join-Path $BackupRoot "Pictures");  Destination = (Join-Path $ProfileDir "Pictures") },
    @{ Name = "Downloads"; Source = (Join-Path $BackupRoot "Downloads"); Destination = (Join-Path $ProfileDir "Downloads") },
    @{ Name = "Favorites"; Source = (Join-Path $BackupRoot "Favorites"); Destination = (Join-Path $ProfileDir "Favorites") }
)

foreach ($Item in $FolderMap) {
    try {
        if (Test-Path $Item.Source) {
            Add-RestoreLog "Restoring $($Item.Name)..."
            Invoke-RoboRestore -Source $Item.Source -Destination $Item.Destination
        }
        else {
            Add-RestoreLog "$($Item.Name) backup not found, skipping."
        }
    }
    catch {
        Add-RestoreLog "WARNING: Failed restoring $($Item.Name): $($_.Exception.Message)"
    }
}

